# owner: platform
from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students given")
    for stud in students:
        if not stud.email:
            raise ProjectError(
                f"no email for {stud.display_name}"
            )


def _cell(stud: Student) -> tuple:
    return (stud.display_name, stud.section, stud.email)


def _widths(cells: list) -> list:
    return [
        max(len(cell[col]) for cell in cells)
        for col in (0, 1)
    ]


def _line(cell: tuple, wide: list) -> str:
    name, sect, mail = cell
    return f"{name:<{wide[0]}}  {sect:<{wide[1]}}  {mail}"


def contact_rows(students: List[Student]) -> List[str]:
    """Aligned name, section, email rows sorted by name."""
    _check(students)
    cells = sorted(_cell(stud) for stud in students)
    wide = _widths(cells)
    return [_line(cell, wide) for cell in cells]

